//! Cross-implementation conformance.
//!
//! The grid model exists twice: Go in the daemon, Rust here. Two
//! implementations of one wire format drift apart silently, and the symptom is
//! a phone rendering something the daemon never had -- close to impossible to
//! diagnose from a bug report.
//!
//! `fixtures/vt/cross-impl.json` is generated by the Go side (see
//! `go/internal/vt/fixturegen_test.go`). It records, for a deliberately awkward
//! script of terminal writes, the snapshot and row delta the daemon would send
//! and the screen the client should end up with. This replays it.
//!
//! Regenerate with:
//!   cd go && MUXSCALE_UPDATE_FIXTURES=1 go test ./internal/vt -run CrossImpl

use muxscale_core::grid::{Delta, Grid, RowRuns, Snapshot};
use serde::{Deserialize, Deserializer};

/// Go marshals a nil slice as `null`, and serde's `default` only fires for an
/// absent field. Same mismatch the library types had to handle.
fn null_as_empty<'de, D, T>(d: D) -> Result<Vec<T>, D::Error>
where
    D: Deserializer<'de>,
    T: Deserialize<'de>,
{
    Ok(Option::<Vec<T>>::deserialize(d)?.unwrap_or_default())
}

#[derive(Debug, Deserialize)]
struct Step {
    #[allow(dead_code)]
    input_b64: String,
    snapshot: Snapshot,
    #[serde(default, deserialize_with = "null_as_empty")]
    delta: Vec<RowRuns>,
    text: String,
    cursor_x: usize,
    cursor_y: usize,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    cols: usize,
    rows: usize,
    steps: Vec<Step>,
}

fn load() -> Fixture {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/vt/cross-impl.json"
    );
    let data = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("reading {path}: {e}\nGenerate it from the Go side first."));
    serde_json::from_str(&data).expect("fixture is not valid JSON")
}

/// Applying each recorded snapshot must reproduce the daemon's screen exactly.
#[test]
fn snapshots_reproduce_the_daemon_screen() {
    let f = load();
    let mut g = Grid::new(f.cols, f.rows);

    for (i, step) in f.steps.iter().enumerate() {
        g.apply_snapshot(&step.snapshot);
        assert_eq!(
            g.text(),
            step.text,
            "step {i}: snapshot produced a different screen than the daemon had"
        );
        assert_eq!(
            (g.cursor_x, g.cursor_y),
            (step.cursor_x, step.cursor_y),
            "step {i}: cursor position diverged"
        );
    }
    println!("reproduced {} snapshots", f.steps.len());
}

/// The path a real client takes: one initial snapshot, then deltas forever.
/// This is the one that catches drift, because an error compounds instead of
/// being reset by the next snapshot.
#[test]
fn deltas_alone_keep_the_client_in_sync() {
    let f = load();
    let mut g = Grid::new(f.cols, f.rows);

    for (i, step) in f.steps.iter().enumerate() {
        g.apply_delta(&Delta {
            cols: f.cols,
            rows: f.rows,
            cursor_x: step.cursor_x,
            cursor_y: step.cursor_y,
            cursor_off: false,
            lines: step.delta.clone(),
        });
        assert_eq!(
            g.text(),
            step.text,
            "step {i}: the client diverged from the daemon after {} deltas.\n\
             This is the failure the fixture exists to catch: an error here \
             compounds silently until the phone shows something that never \
             existed.",
            i + 1
        );
    }
    println!("stayed in sync across {} deltas", f.steps.len());
}

/// A snapshot after a run of deltas must agree with the delta-only replica.
/// Clients request a fresh snapshot to repair a lost delta, so the two paths
/// converging is what makes that repair correct.
#[test]
fn snapshot_and_delta_paths_agree() {
    let f = load();
    let mut by_delta = Grid::new(f.cols, f.rows);
    let mut by_snapshot = Grid::new(f.cols, f.rows);

    for (i, step) in f.steps.iter().enumerate() {
        by_delta.apply_delta(&Delta {
            cols: f.cols,
            rows: f.rows,
            cursor_x: step.cursor_x,
            cursor_y: step.cursor_y,
            cursor_off: false,
            lines: step.delta.clone(),
        });
        by_snapshot.apply_snapshot(&step.snapshot);

        assert_eq!(
            by_delta.text(),
            by_snapshot.text(),
            "step {i}: the delta path and the snapshot path disagree, so \
             repairing a lost delta with a snapshot would visibly change the screen"
        );

        // Cell-level, not just text: attributes are invisible in text output
        // and are exactly where a subtle divergence hides.
        for y in 0..f.rows {
            for x in 0..f.cols {
                assert_eq!(
                    by_delta.at(x, y),
                    by_snapshot.at(x, y),
                    "step {i}: cell ({x},{y}) differs between the delta and snapshot paths"
                );
            }
        }
    }
}

/// Wide characters must occupy the same columns in both implementations. A
/// disagreement shifts every subsequent column on the row.
#[test]
fn wide_character_columns_match_the_daemon() {
    let f = load();
    let mut g = Grid::new(f.cols, f.rows);
    let mut saw_wide = false;

    for step in &f.steps {
        g.apply_snapshot(&step.snapshot);
        for y in 0..f.rows {
            for x in 0..f.cols {
                if g.at(x, y).wide {
                    saw_wide = true;
                    // A continuation cell must always follow its leader.
                    assert!(x > 0, "a wide continuation cell cannot be in column 0");
                    let leader = g.at(x - 1, y);
                    assert!(
                        !leader.wide,
                        "two continuation cells in a row means the width \
                         calculation disagrees with the daemon"
                    );
                }
            }
        }
    }
    assert!(saw_wide, "the fixture should exercise wide characters");
}
